"""Build a standalone HTML test presentation from captured real-browser evidence."""
import base64, html, json
from datetime import datetime, timezone
from pathlib import Path
root=Path(__file__).resolve().parents[2]
out=root/'audit-results/canvas-integration'
evidence=list({item['name']:item for item in json.loads((out/'evidence.json').read_text())}.values())
checks=json.loads((out/'boundaries.json').read_text())
students=json.loads((out/'students.json').read_text())
ids=json.loads((out/'course.json').read_text())
escape=html.escape
slides=[]
slides.append('''<section class="slide cover"><div class="eyebrow">FINANCEBOT × CANVAS / LOCAL ACCEPTANCE</div><h1>多个班级。<br>一个 FinanceBot 课程。</h1><p class="lead">真实 Canvas OAuth、已有课程关联、材料导入，以及 20 位学生的 CWL 自动入课测试。</p><div class="metrics"><div><b>20 / 20</b><span>真实 SAML 学生登录</span></div><div><b>93</b><span>单元与回归测试通过</span></div><div><b>101 + 102</b><span>合并为 20 个独立身份</span></div></div><div class="note">测试环境：本地 Canvas :80 · FinanceBot :6118 · 本地 SAML IdP :6122<br>测试日期：2026-09-28 · 所有学生均为专用虚拟测试身份</div><p class="hint">点击「下一步」查看实际操作截图。截图可滚动，也可点击放大。</p></section>''')
for i,item in enumerate(evidence,1):
    image=base64.b64encode((out/item['screenshot']).read_bytes()).decode()
    item['at']=datetime.fromtimestamp((out/item['screenshot']).stat().st_mtime,timezone.utc).isoformat()
    focus={'05-multiselect':.6,'06-roster':0,'07-files':1,'08-import':1,'11-existing-linked':0,'13-all-matched':0,'15-drop':0,'16-missing-puid':0,'18-restored':0}.get(item['name'],0)
    slides.append(f'''<section class="slide" data-focus="{focus}"><div class="eyebrow">STEP {i:02d} / VERIFIED IN LOCAL CANVAS</div><h2>{escape(item['title'])}</h2><p class="description">{escape(item['detail'])}</p><div class="shot"><button class="expand" aria-label="放大截图"><img src="data:image/png;base64,{image}" alt="{escape(item['title'])}的实际浏览器截图"></button></div><div class="caption"><span class="pass">● 已验证</span><span>{escape(item['at'][:19].replace('T',' '))} UTC · 实际浏览器截图 · 非原型</span></div></section>''')
rows=''.join(f'<tr><td>{escape(s["student"])}</td><td>{escape(s["name"])}</td><td class="yes">自动入课成功</td><td>0</td></tr>' for s in students)
checkrows=''.join(f'<li><span class="pass">✓</span> {escape(c["name"])}</li>' for c in checks)
slides.append(f'''<section class="slide summary"><div class="eyebrow">ACCEPTANCE / RESULTS</div><h2>身份、权限与课程状态均已验证。</h2><div class="result-grid"><div class="result-card"><h3>安全与边界检查</h3><ul>{checkrows}</ul></div><div class="result-card"><h3>代码验证</h3><p><strong>93 项通过</strong>：Canvas component / service / routes、Users、Materials、Course deletion。</p><p>TypeScript server + client 类型检查通过。真实导入文件已处理为 <code>ready</code>；重复导入不产生副本。新增 Canvas 页面 WCAG A/AA 扫描 0 违规；390px 窄屏无页面横向溢出。</p><h3>保留现有体验</h3><p>My Courses 的共享 course card 未改动。新增入口位于卡片上方、课程 Settings 和 Materials 中。</p><h3>生产环境仍需确认</h3><p>本次验证是本地测试。UBC production 需要允许教师读取 Canvas SIS identity，并确认 <code>integration_id</code> 与本应用 SAML 的 <code>ubcEduCwlPuid</code> 是同一个标识。未部署或测试 staging / production。</p></div></div><details><summary>展开查看 20 位学生逐一登录结果</summary><table><thead><tr><th>本地 CWL 测试账户</th><th>显示姓名</th><th>结果</th><th>重复角色</th></tr></thead><tbody>{rows}</tbody></table></details></section>''')
slides.append(f'''<section class="slide review"><div class="eyebrow">READY FOR YOUR REVIEW</div><h2>现在可以检查实现成果。</h2><div class="review-grid"><a href="http://localhost:6118/#/instructor/course/{ids['courseId']}/canvas" target="_blank" rel="noopener"><span>01</span><h3>101 + 102 合并课程 ↗</h3><p>已发布 · 20 名虚拟学生 · Canvas 材料 ready</p></a><a href="http://localhost:6118/#/instructor/course/{ids['existingCourseId']}/canvas" target="_blank" rel="noopener"><span>02</span><h3>已有课程补关联 ↗</h3><p>关联 Canvas 201 · 5 名学生 · 保留 draft</p></a><a href="http://localhost:6118/#/instructor/courses" target="_blank" rel="noopener"><span>03</span><h3>原 My Courses 页面 ↗</h3><p>原课程卡片 + 新增 Canvas 入口</p></a></div><div class="note">使用本地 faculty 测试账号登录 FinanceBot 后查看教师页面。连接和课程数据均已保留。学生使用 canvas_student_01 至 canvas_student_20；本地测试密码沿用 username=password 约定。<br>演示账号仅用于本地测试。</div><h3>本次范围</h3><p>支持多个 Canvas course shell 对应一个 FinanceBot course；每个 shell 的原生 sections 自动包含在其花名册中。材料为显式导入的副本；成绩回写和自动覆盖材料不在本次范围内。</p></section>''')
nav=''.join(f'<button class="step" data-index="{i}">{"概览" if i==0 else str(i).zfill(2) if i<=len(evidence) else "结果" if i==len(evidence)+1 else "检查成果"}</button>' for i in range(len(slides)))
css='''*{box-sizing:border-box}html{color-scheme:light}body{margin:0;background:#eef2ed;color:#20372b;font-family:Inter,-apple-system,BlinkMacSystemFont,"Segoe UI","PingFang SC",sans-serif}button,a{-webkit-tap-highlight-color:transparent}button{font:inherit;cursor:pointer}header{height:66px;padding:0 34px;background:#153e2c;color:#fff;display:flex;align-items:center;justify-content:space-between;position:sticky;top:0;z-index:5}header b{letter-spacing:.12em;font-size:13px}header span{font-size:12px;color:#cedbd0}main{max-width:1450px;margin:0 auto;padding:32px 46px 112px}.slide{display:none;animation:enter .2s ease}.slide.active{display:block}.eyebrow{font-size:11px;letter-spacing:.2em;font-weight:800;color:#52745c;margin:10px 0 18px}h1{font-size:clamp(42px,5.2vw,76px);line-height:1.16;letter-spacing:-.045em;margin:22px 0 26px;max-width:1000px}h2{font-size:clamp(26px,3.3vw,42px);letter-spacing:-.035em;line-height:1.25;margin:0 0 14px}h3{font-size:18px;margin:10px 0 14px}.lead{font-size:22px;line-height:1.65;max-width:950px;color:#4c6556}.description{font-size:17px;line-height:1.7;margin:0 0 24px;max-width:1100px;color:#4d6254}.cover{padding-top:25px}.metrics{display:grid;grid-template-columns:repeat(3,1fr);margin:42px 0 28px;gap:18px}.metrics div{background:#fff;border:1px solid #d6e0d7;padding:26px;border-radius:12px}.metrics b{font-size:34px;display:block}.metrics span{display:block;font-size:14px;margin-top:12px;color:#627367}.note{background:#e0e9df;border-left:4px solid #6a896e;padding:22px 26px;line-height:1.9;margin:28px 0;color:#405747;font-size:14px}.hint{font-size:13px;color:#697c6a}.shot{height:62vh;min-height:340px;overflow:auto;background:#e3e9e2;border:1px solid #cfdacf;border-radius:12px;box-shadow:0 12px 35px #153e2c0b}.shot button{display:block;border:0;padding:0;background:transparent;width:100%;cursor:zoom-in}.shot img{width:auto;max-width:100%;display:block;margin:auto}.caption{display:flex;justify-content:space-between;gap:15px;font-size:11px;color:#6b7c6e;margin-top:13px}.pass,.yes{color:#216343;font-weight:700}.result-grid{display:grid;grid-template-columns:1fr 1fr;gap:24px;margin-top:30px}.result-card{background:#fff;padding:26px;border:1px solid #d6e0d7;border-radius:12px;font-size:14px;line-height:1.75}.result-card ul{padding:0;list-style:none}.result-card li{margin:12px 0}.result-card h3:not(:first-child){margin-top:25px}details{margin:24px 0;padding:20px;background:white;border-radius:12px;overflow:auto}summary{cursor:pointer;font-weight:650}table{width:100%;border-collapse:collapse;margin-top:20px;font-size:13px}th,td{text-align:left;padding:12px;border-bottom:1px solid #e1e7df}.review-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:22px;margin:38px 0}.review-grid a{display:block;background:#fff;padding:28px;border:1px solid #d6e0d7;border-radius:12px;color:inherit;text-decoration:none}.review-grid a:hover{border-color:#3c7248}.review-grid span{font-size:32px;color:#8ba98f}.review-grid p{font-size:14px;line-height:1.7}.review>p{line-height:1.8}footer{position:fixed;bottom:0;left:0;right:0;background:#fff;border-top:1px solid #d5dfd5;display:flex;align-items:center;gap:18px;padding:16px 30px;z-index:5}nav{display:flex;gap:4px;overflow:auto;flex:1}.step{border:0;background:transparent;color:#526759;min-width:32px;height:32px;font-size:11px;border-radius:6px}.step.current{background:#dce9dd;color:#17432d;font-weight:800}.control{padding:11px 18px;border:1px solid #b9cbbb;background:white;color:#264b32;border-radius:8px;white-space:nowrap}.primary{background:#245839;color:white;border-color:#245839}.control:disabled{opacity:.4;cursor:default}button:focus-visible,a:focus-visible,summary:focus-visible{outline:3px solid #bb8331;outline-offset:3px}#position{min-width:50px;font-size:12px;color:#607668}dialog{width:96vw;height:94vh;max-width:none;max-height:none;border:0;border-radius:12px;padding:0;background:#eef2ed}dialog::backdrop{background:#102318ce}dialog .close{position:sticky;top:12px;float:right;margin:12px;border:0;border-radius:30px;padding:10px 18px;background:#153e2c;color:white;z-index:5}dialog img{width:100%;display:block}@keyframes enter{from{opacity:.5;transform:translateY(5px)}to{opacity:1;transform:none}}@media(max-width:700px){header{padding:0 18px}header span{display:none}main{padding:22px 20px 110px}.metrics,.result-grid,.review-grid{grid-template-columns:1fr}.metrics{gap:10px;margin:24px 0}.metrics div{padding:16px}.metrics b{font-size:25px}.shot{height:60vh;min-height:300px}.caption{display:block;line-height:1.8}footer{padding:12px;gap:8px}nav{display:none}.lead{font-size:18px}.control{padding:10px 14px}#position{margin-right:auto}}@media print{header,footer{display:none}main{padding:0}.slide,.slide.active{display:block;break-after:page;animation:none}.shot{height:auto;max-height:none;overflow:visible;box-shadow:none}.shot img{max-height:230mm;object-fit:contain;object-position:top}.cover{padding:20mm}.note{break-inside:avoid}}'''
script='''const slides=[...document.querySelectorAll('.slide')],steps=[...document.querySelectorAll('.step')];let current=0;const prev=document.getElementById('prev'),next=document.getElementById('next');function show(n){current=Math.max(0,Math.min(slides.length-1,n));slides.forEach((s,i)=>s.classList.toggle('active',i===current));steps.forEach((s,i)=>{s.classList.toggle('current',i===current);s.setAttribute('aria-current',i===current?'step':'false')});prev.disabled=current===0;next.disabled=current===slides.length-1;document.getElementById('position').textContent=`${current+1} / ${slides.length}`;location.hash=String(current+1);window.scrollTo(0,0);const shot=slides[current].querySelector('.shot');if(shot)requestAnimationFrame(()=>{shot.scrollTop=(shot.scrollHeight-shot.clientHeight)*Number(slides[current].dataset.focus||0)})}prev.onclick=()=>show(current-1);next.onclick=()=>show(current+1);steps.forEach(s=>s.onclick=()=>show(Number(s.dataset.index)));document.addEventListener('keydown',e=>{if(document.querySelector('dialog').open)return;if(e.key==='ArrowRight')show(current+1);if(e.key==='ArrowLeft')show(current-1)});const dialog=document.querySelector('dialog');document.querySelectorAll('.expand').forEach(b=>b.onclick=()=>{dialog.querySelector('img').src=b.querySelector('img').src;dialog.querySelector('img').alt=b.querySelector('img').alt;dialog.showModal()});dialog.querySelector('.close').onclick=()=>dialog.close();show(Number(location.hash.slice(1)||1)-1);'''
page=f'''<!doctype html><html lang="zh-CN"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>FinanceBot × Canvas · 本地测试报告</title><style>{css}</style></head><body><header><b>FINANCEBOT × CANVAS</b><span>IMPLEMENTATION & LOCAL TEST EVIDENCE · 28 SEP 2026</span></header><main>{''.join(slides)}</main><footer><span id="position" aria-live="polite"></span><nav aria-label="测试步骤">{nav}</nav><button class="control" id="prev">← 上一步</button><button class="control primary" id="next">下一步 →</button></footer><dialog aria-label="截图全尺寸查看"><button class="close">关闭 ×</button><img alt=""></dialog><script>{script}</script></body></html>'''
report=out/'presentation/index.html';report.parent.mkdir(exist_ok=True);report.write_text(page)
print(f'Built {len(slides)} slides, {len(evidence)} real screenshots, {len(students)} verified students: {report}')
